# Research-only frozen Stage-A Monte Carlo orchestration for TRSC.
.trsc_stage_a <- list(
 design_sha256="7ba2f3086a1649751732a6853c7fff06825608ea6cc0435a6ab6397469b1cf51",
 historical_design_sha256="5a323b781a915ee313d5187c7d59d53a650947b4725f9af89b81ce42f678f6b8",
 registry_sha256="b69df091e331c6d93e786bf0e6300babb4a5d4b76e5cf6f09c3c242d16a51480",
 candidate_sha256="8f0a00b3ce3aef2ac294ab9946f2701f7977730ab9fa09038df0cb51e80f1be5",
 epsilon_sha256="e5513f30939373cb98edfff718d2e74805095d97635741f407baf3abd029c017",
 cells=179L,attempts=73400L,smoke_seeds=c(11L,12L,101L))
.trsc_val<-function(x,d=NA)if(is.null(x)||!length(x))d else x
trsc_sim_sha256_file<-function(path){
 if(!file.exists(path))stop("Missing file: ",path,call.=FALSE)
 x<-Sys.which("sha256sum");if(nzchar(x))return(strsplit(system2(x,path,stdout=TRUE)[1],"[[:space:]]+")[[1]][1])
 x<-Sys.which("shasum");if(nzchar(x))return(strsplit(system2(x,c("-a","256",path),stdout=TRUE)[1],"[[:space:]]+")[[1]][1])
 x<-Sys.which("openssl");if(nzchar(x))return(sub("^.*= ","",system2(x,c("dgst","-sha256",path),stdout=TRUE)[1]))
 stop("No SHA-256 command is available.",call.=FALSE)}
trsc_sim_frozen_paths<-function(root="research/simulations")list(
 design=file.path(root,"SIMULATION_DESIGN.md"),cells=file.path(root,"FROZEN_CELL_REGISTRY.csv"),
 candidates=file.path(root,"FROZEN_CANDIDATE_LIBRARIES.csv"),epsilon=file.path(root,"FROZEN_DEPLOYMENT_EPSILON.csv"))
trsc_sim_registry_hashes<-function(root="research/simulations")vapply(trsc_sim_frozen_paths(root),trsc_sim_sha256_file,character(1))
.trsc_param_key<-function(x){omit<-c("cell_index","cell_id","panel","repetition_class","repetitions","generator_override","analysis_tags","continuation_in_class_expected");use<-setdiff(names(x),omit);apply(x[use],1,function(z)paste(ifelse(is.na(z),"<NA>",z),collapse="|"))}
trsc_sim_validate_frozen_registries<-function(root="research/simulations"){
 p<-trsc_sim_frozen_paths(root);if(!all(file.exists(unlist(p))))stop("Frozen Stage-A files are incomplete.",call.=FALSE)
 h<-trsc_sim_registry_hashes(root);e<-c(design=.trsc_stage_a$design_sha256,cells=.trsc_stage_a$registry_sha256,candidates=.trsc_stage_a$candidate_sha256,epsilon=.trsc_stage_a$epsilon_sha256)
 if(!identical(unname(h),unname(e)))stop("Frozen hash mismatch: ",paste(names(h)[h!=e],collapse=", "),call.=FALSE)
 cells<-read.csv(p$cells,stringsAsFactors=FALSE,na.strings="");cand<-read.csv(p$candidates,stringsAsFactors=FALSE);eps<-read.csv(p$epsilon,stringsAsFactors=FALSE)
 if(nrow(cells)!=179L||sum(cells$repetitions)!=73400L)stop("Frozen count mismatch.",call.=FALSE)
 if(!identical(as.integer(cells$cell_index),seq_len(nrow(cells)))||anyDuplicated(cells$cell_id))stop("Cell IDs are not ordered and unique.",call.=FALSE)
 if(anyDuplicated(.trsc_param_key(cells)))stop("Duplicate scientific parameter vectors.",call.=FALSE)
 pre<-c("constant","affine","curved","abrupt","exact_duplication","near_redundancy","weak_excitation","reference_mismatch","interior","persistent_errors","separated_face","vanishing_margin","face_change")
 post<-c("persistence","affine","hull_exit","exact_ambiguity","near_redundancy","weak_excitation","full_rank","curved","abrupt")
 idx<-ifelse(cells$layer=="pre_treatment_predictive",match(cells$scenario,pre),13L+match(cells$scenario,post))
 if(anyNA(idx)||!identical(as.integer(cells$scenario_index),as.integer(idx)))stop("Scenario indices differ from generator order.",call.=FALSE)
 sizes<-table(cand$library_id);want<-c(L1=1L,L4=4L,L12=12L,L24=24L)
 if(!identical(as.integer(sizes[names(want)]),as.integer(want)))stop("Candidate library mismatch.",call.=FALSE)
 if(!identical(as.numeric(eps$epsilon_over_D),c(0,.01,.1,.5,1)))stop("Epsilon grid mismatch.",call.=FALSE)
 if(!any(cells$panel=="E1"&cells$J_requested==120)||!any(cells$panel=="P2"&cells$near_distance==0)||!any(cells$panel=="P4"&cells$radius_rule=="zero"))stop("A declared difficult cell was removed.",call.=FALSE)
 list(cells=cells,candidates=cand,epsilon=eps,hashes=h,registry_hash=unname(h[["cells"]]),cell_count=nrow(cells),attempted_repetitions=as.integer(sum(cells$repetitions)))}
trsc_sim_candidate_spec<-function(id,frozen=trsc_sim_validate_frozen_registries()){
 d<-frozen$candidates[frozen$candidates$library_id==id,,drop=FALSE];if(!nrow(d))stop("Unknown predictive library.",call.=FALSE);d<-d[order(d$candidate_index),,drop=FALSE]
 list(library_id=id,candidates=d,q=unique(as.integer(d$predictive_q)),kappa=unique(as.numeric(d$kappa)),bandwidths=unique(as.integer(d$h)))}
trsc_sim_frozen_seed<-function(scenario_index,repetition){s<-as.integer(scenario_index);r<-as.integer(repetition);if(length(s)!=1||is.na(s)||s<1||s>22||length(r)!=1||is.na(r)||r<1)stop("Invalid scenario/repetition.",call.=FALSE);as.integer(1000000L+10000L*s+r)}
trsc_sim_attempt_key<-function(hash,cell_id,repetition)paste(hash,cell_id,as.integer(repetition),sep=":")
trsc_sim_attempt_table<-function(frozen=trsc_sim_validate_frozen_registries()){
 z<-lapply(seq_len(nrow(frozen$cells)),function(i){x<-frozen$cells[i,,drop=FALSE];r<-seq_len(as.integer(x$repetitions));data.frame(registry_hash=frozen$registry_hash,cell_id=x$cell_id,cell_index=as.integer(x$cell_index),panel=x$panel,scenario=x$scenario,scenario_index=as.integer(x$scenario_index),repetition=r,seed=vapply(r,function(k)trsc_sim_frozen_seed(x$scenario_index,k),integer(1)),stringsAsFactors=FALSE)})
 out<-do.call(rbind,z);rownames(out)<-NULL;out$primary_key<-mapply(trsc_sim_attempt_key,out$registry_hash,out$cell_id,out$repetition,USE.NAMES=FALSE)
 if(anyDuplicated(out$primary_key))stop("Duplicate attempt keys.",call.=FALSE);if(any(out$seed %in% .trsc_stage_a$smoke_seeds))stop("Smoke seed entered scientific table.",call.=FALSE);out}
trsc_sim_support_directions<-function(H){H<-as.integer(H);if(is.na(H)||H<1)stop("H must be positive.",call.=FALSE);out<-list();for(h in seq_len(H)){e<-rep(0,H);e[h]<-1;out[[paste0("e",h)]]<-e;out[[paste0("minus_e",h)]]<--e};out$all_ones<-rep(1,H);out$minus_all_ones<-rep(-1,H);out$equal_weight_mean<-rep(1/H,H);out$minus_equal_weight_mean<-rep(-1/H,H);out}
trsc_sim_probability_budget<-function(alpha=.05,M,alpha_geometry=0,alpha_mixing=0,alpha_other=0,fitting_failure=0,alpha_anchor=NULL){
 M<-as.integer(M);if(is.na(M)||M<1)stop("M must be positive.",call.=FALSE);if(is.null(alpha_anchor))alpha_anchor<-alpha-alpha_geometry-alpha_mixing-alpha_other
 if(any(c(alpha_anchor,alpha_geometry,alpha_mixing,alpha_other,fitting_failure)<0)||alpha_anchor+alpha_geometry+alpha_mixing+alpha_other>alpha+1e-15)stop("Invalid probability allocation.",call.=FALSE)
 per<-alpha_anchor/M;path<-per-fitting_failure;if(path<0)stop("Fitting failure exceeds per-candidate anchor budget.",call.=FALSE)
 list(alpha=alpha,alpha_anchor=alpha_anchor,alpha_geometry=alpha_geometry,alpha_mixing=alpha_mixing,alpha_other=alpha_other,M=M,per_candidate_anchor_budget=per,fitting_failure=fitting_failure,alpha_path=path)}
trsc_sim_validate_nominal_risk_inputs<-function(inputs){req<-c("path_risk_bound","noise_covariance_bound","approximation_residual_bound","target_roughness_bound","restricted_coercivity_bound","fitting_to_cutoff_bound","predictive_to_causal_transfer_bound","QP_objective_allowance","geometry_certificate");if(!is.list(inputs))stop("Nominal risk inputs must be a list.",call.=FALSE);bad<-req[!req%in%names(inputs)];if(length(bad))stop("Nominal risk certificate is missing valid numerical inputs: ",paste(bad,collapse=", "),call.=FALSE);invisible(TRUE)}
trsc_sim_nominal_inference_gate<-function()list(status="NOT READY",alpha=.05,reason="Every numerical theorem input required by trsc_anchor_from_risk is not frozen.",missing_inputs=c("uniform_path_risk_envelope","noise_covariance_upper_bound","approximation_residual_bound","target_roughness_bound","restricted_coercivity_bound","fitting_to_cutoff_bound","predictive_to_causal_transfer_bound","QP_objective_allowance"))
trsc_sim_execution_gate<-function(frozen=trsc_sim_validate_frozen_registries()){a<-trsc_sim_attempt_table(frozen);ok<-frozen$cell_count==179L&&frozen$attempted_repetitions==73400L&&nrow(a)==73400L&&!anyDuplicated(a$primary_key);list(status=if(ok)"READY"else"NOT READY",cell_count=frozen$cell_count,attempted_repetitions=frozen$attempted_repetitions,registry_hash=frozen$registry_hash)}
trsc_sim_resolve_radius<-function(cell,truth){q<-as.integer(cell$structural_q);H<-as.integer(cell$H);D<-as.numeric(cell$D);rmin<-trsc_min_radius(truth$geometry_true,truth$anchor_true,q,H,previous=if(q==2)truth$previous_true else NULL);u<-as.numeric(rmin$upper);rule<-as.character(cell$radius_rule);R<-switch(rule,zero=0,rmin=u,rmin_plus_0.01D=u+.01*D,rmin_plus_0.1D=u+.1*D,rmin_plus_D=u+D,four_sqrtH_D=4*sqrt(H)*D,stop("Unknown radius rule.",call.=FALSE));list(Rmin_lower=as.numeric(rmin$lower),Rmin_upper=as.numeric(rmin$upper),Rmin_used=u,R=as.numeric(R),radius_rule=rule,structural_infeasible=R+1e-14<as.numeric(rmin$lower),provenance="population Rmin is design/oracle information; not feasible data-driven tuning",certificate_status=rmin$status)}
.trsc_actual_dimensions<-function(cell,obj)if(cell$layer=="pre_treatment_predictive")list(J=as.integer(obj$J),rank=NA_integer_)else list(J=as.integer(obj$parameters$J),rank=as.integer(obj$truth$geometry_true$diagnostics$empirical_rank))
.trsc_verify_dimensions<-function(cell,obj){a<-.trsc_actual_dimensions(cell,obj);ej<-as.integer(cell$J_effective);er<-suppressWarnings(as.integer(cell$rank_effective));if(!is.na(ej)&&a$J!=ej)stop("Generated effective J differs from registry.",call.=FALSE);if(!is.na(er)&&a$rank!=er)stop("Generated effective rank differs from registry.",call.=FALSE);a}
.trsc_support_row<-function(set,a,layer,direction){hi<-trsc_support(set,a);lo<-trsc_support(set,-a);get<-function(x,n,d=NA)if(is.null(x[[n]]))d else x[[n]];uhi<-get(hi,"dual_objective",NA_real_);ulo<-get(lo,"dual_objective",NA_real_);data.frame(layer=layer,direction=direction,lower=-lo$upper,upper=hi$upper,width=hi$upper+lo$upper,upper_status=hi$status,lower_status=lo$status,upper_primal_lower=get(hi,"primal_lower",NA_real_),lower_primal_lower=get(lo,"primal_lower",NA_real_),upper_primal_violation=get(hi$primal_feasibility,"violation",NA_real_),lower_primal_violation=get(lo$primal_feasibility,"violation",NA_real_),upper_dual_feasible=isTRUE(get(hi,"dual_feasibility",FALSE)),lower_dual_feasible=isTRUE(get(lo,"dual_feasibility",FALSE)),upper_dual_objective=uhi,lower_dual_objective=ulo,upper_dual_residual=get(hi$certificate,"stationarity_residual",NA_real_),lower_dual_residual=get(lo$certificate,"stationarity_residual",NA_real_),upper_certified_correction=if(is.finite(uhi))hi$upper-uhi else NA_real_,lower_certified_correction=if(is.finite(ulo))lo$upper-ulo else NA_real_,upper_certified_gap=.trsc_val(hi$certified_gap,NA_real_),lower_certified_gap=.trsc_val(lo$certified_gap,NA_real_),upper_certificate_method=get(hi$certificate,"method",NA_character_),lower_certificate_method=get(lo$certificate,"method",NA_character_),upper_fallback=identical(get(hi$certificate,"method",""),"simplex_hull"),lower_fallback=identical(get(lo$certificate,"method",""),"simplex_hull"),stringsAsFactors=FALSE)}
trsc_sim_post_frozen_metrics<-function(cell,run,truth,radius,frozen){q<-as.integer(cell$structural_q);H<-as.integer(cell$H);R<-radius$R;oracle<-trsc_counterfactual_set(truth$geometry_true,truth$x_post,truth$anchor_true,q,R,previous=if(q==2)truth$previous_true else NULL,type="population");semi<-trsc_sim_post_semifeasible(run,truth);sets<-list(oracle_population_set=oracle,plugin_no_coverage=run$plugin,semi_feasible_population_geometry=semi,feasible_diameter_bound=run$outer);dirs<-trsc_sim_support_directions(H);rows<-list();k<-0L;for(layer in names(sets))for(nm in names(dirs)){k<-k+1L;rows[[k]]<-.trsc_support_row(sets[[layer]],dirs[[nm]],layer,nm)};supports<-do.call(rbind,rows);rownames(supports)<-NULL;or<-supports[supports$layer=="oracle_population_set",c("direction","lower","upper","upper_primal_lower","lower_primal_lower")];names(or)<-c("direction","oracle_lower","oracle_upper","oracle_upper_primal_lower","oracle_negative_primal_lower");supports<-merge(supports,or,by="direction",all.x=TRUE,sort=FALSE);hulls<-do.call(rbind,lapply(names(dirs),function(nm){v<-sweep(truth$x_post,1,dirs[[nm]],"*");lo<-sum(apply(v,1,min));hi<-sum(apply(v,1,max));data.frame(direction=nm,unrestricted_hull_lower=lo,unrestricted_hull_upper=hi,unrestricted_hull_width=hi-lo,stringsAsFactors=FALSE)}));supports<-merge(supports,hulls,by="direction",all.x=TRUE,sort=FALSE);supports$width_to_unrestricted_hull<-ifelse(supports$unrestricted_hull_width>0,supports$width/supports$unrestricted_hull_width,NA_real_);supports$lower_endpoint_comparison<-ifelse(supports$lower<=supports$oracle_lower,"certified_covered",ifelse(is.finite(supports$oracle_negative_primal_lower)&supports$lower> -supports$oracle_negative_primal_lower,"certified_not_covered","unresolved"));supports$upper_endpoint_comparison<-ifelse(supports$upper>=supports$oracle_upper,"certified_covered",ifelse(is.finite(supports$oracle_upper_primal_lower)&supports$upper<supports$oracle_upper_primal_lower,"certified_not_covered","unresolved"));getw<-function(layer,nm){z<-supports[supports$layer==layer&supports$direction==nm,"width"];if(length(z))z[1]else NA_real_};gets<-function(layer,nm){z<-supports[supports$layer==layer&supports$direction==nm,c("lower_status","upper_status"),drop=FALSE];if(nrow(z))paste(z$lower_status[1],z$upper_status[1],sep="/")else NA_character_};decomposition<-do.call(rbind,lapply(names(dirs),function(nm){pw<-getw("oracle_population_set",nm);pl<-getw("plugin_no_coverage",nm);sw<-getw("semi_feasible_population_geometry",nm);ow<-getw("feasible_diameter_bound",nm);data.frame(direction=nm,population_width=pw,plugin_width=pl,semi_feasible_width=sw,outer_width=ow,total_outer_width=ow,statistical_enlargement=ow-pw,population_enclosure_status=gets("oracle_population_set",nm),plugin_enclosure_status=gets("plugin_no_coverage",nm),semi_feasible_enclosure_status=gets("semi_feasible_population_geometry",nm),outer_enclosure_status=gets("feasible_diameter_bound",nm),stringsAsFactors=FALSE)}));base<-trsc_sim_post_metrics(run,truth,a=rep(1,H));selected_fit_name<-run$workflow$selected$candidate_specification$fit_name;selected_fit<-attr(run$workflow$candidate_library,"fits")[[selected_fit_name]];fit_periods<-as.integer(selected_fit$periods);estimated_beta<-truth$geometry_true$B%*%unclass(stats::weights(selected_fit));true_beta<-truth$beta_true[,fit_periods,drop=FALSE];base$integrated_profile_loss<-mean(colSums((estimated_beta-true_beta)^2));pop_bands<-trsc_bounds(oracle);all_row<-supports[supports$layer=="oracle_population_set"&supports$direction=="all_ones",,drop=FALSE];base$joint_population_lower_enclosure<-all_row$lower[1];base$joint_population_upper_enclosure<-all_row$upper[1];base$datewise_relaxed_lower<-sum(pop_bands$lower);base$datewise_relaxed_upper<-sum(pop_bands$upper);base$Rmin_lower<-radius$Rmin_lower;base$Rmin_upper<-radius$Rmin_upper;base$Rmin_used<-radius$Rmin_used;base$R_used<-R;base$radius_rule<-radius$radius_rule;base$library_id<-cell$predictive_library;base$library_candidate_count<-sum(frozen$candidates$library_id==cell$predictive_library);base$library_probability_cost<-run$outer$coverage$failure_probability;base$support_fallback_frequency<-mean(supports$upper_fallback|supports$lower_fallback);base$nominal_inference_status<-trsc_sim_nominal_inference_gate()$status;mods<-list();m<-0L;gs<-list(population=truth$geometry_true,empirical=run$outer$geometry);for(gn in names(gs))for(h in seq_len(H))for(i in seq_len(nrow(frozen$epsilon))){m<-m+1L;ep<-frozen$epsilon$epsilon_over_D[i]*as.numeric(cell$D);z<-trsc_deployment_modulus(gs[[gn]],truth$x_post[h,],ep);du<-.trsc_val(z$dual_objective,NA_real_);mods[[m]]<-data.frame(geometry_layer=gn,horizon=h,epsilon_over_D=frozen$epsilon$epsilon_over_D[i],epsilon=ep,modulus_upper=z$upper,status=z$status,primal_violation=z$primal_feasibility$violation,dual_feasible=isTRUE(z$dual_feasibility),dual_objective=du,dual_residual=.trsc_val(z$certificate$stationarity_residual,NA_real_),certified_correction=if(is.finite(du))z$upper-du else NA_real_,certified_gap=.trsc_val(z$certified_gap,NA_real_),certificate_method=z$certificate$method,fallback=identical(z$certificate$method,"simplex_hull"),stringsAsFactors=FALSE)};prop<-if(q==2){x<-trsc_anchor_propagation(run$outer$anchor_certificate,seq_len(H));x$layer<-"feasible_diameter_bound";x}else data.frame();list(summary=base,supports=supports,decomposition=decomposition,modulus=do.call(rbind,mods),propagation=prop)}
trsc_sim_frozen_attempt<-function(cell,repetition,frozen){r<-as.integer(repetition);if(nrow(cell)!=1||is.na(r)||r<1||r>cell$repetitions)stop("Attempt outside frozen cell.",call.=FALSE);seed<-trsc_sim_frozen_seed(cell$scenario_index,r);if(seed%in%.trsc_stage_a$smoke_seeds)stop("Reserved smoke seed.",call.=FALSE);list(registry_hash=frozen$registry_hash,cell_id=cell$cell_id,cell_index=cell$cell_index,panel=cell$panel,scenario=cell$scenario,scenario_index=cell$scenario_index,repetition=r,seed=seed,primary_key=trsc_sim_attempt_key(frozen$registry_hash,cell$cell_id,r))}
trsc_sim_result_path<-function(dir,a)file.path(dir,a$panel,a$cell_id,paste0(gsub("[^A-Za-z0-9_.-]","_",a$primary_key),".rds"))
trsc_sim_atomic_save<-function(x,path){dir.create(dirname(path),recursive=TRUE,showWarnings=FALSE);tmp<-tempfile(".",dirname(path));on.exit(unlink(tmp),add=TRUE);saveRDS(x,tmp);if(!file.rename(tmp,path))stop("Atomic rename failed.",call.=FALSE);invisible(path)}
.trsc_fit_cache_key<-function(cell,a){f<-c("scenario","T","J_requested","rank_requested","sigma","gap","velocity","near_distance","dependence","predictive_library","structural_q","D");paste(c(a$seed,vapply(f,function(n){x<-cell[[n]];if(is.na(x))"<NA>"else as.character(x)},character(1))),collapse="__")}
.trsc_retarget<-function(base,observed,protocol){id<-base$workflow$selection$selected_name;ac<-base$candidate_certificates[[id]];base$outer<-trsc_confidence_set(observed$x_post,ac,base$geometry_certificate,protocol$q,protocol$R,library=base$candidate_certificates);base$plugin<-trsc_counterfactual_set(base$outer$geometry,observed$x_post,base$center,protocol$q,protocol$R,previous=base$previous);base$protocol<-protocol;base}
.trsc_cached_fit<-function(observed,protocol,cell,a,cache_dir=NULL){if(is.null(cache_dir))return(list(run=trsc_sim_post_feasible(observed,protocol),hit=FALSE));dir.create(cache_dir,recursive=TRUE,showWarnings=FALSE);path<-file.path(cache_dir,paste0(gsub("[^A-Za-z0-9_.-]","_",.trsc_fit_cache_key(cell,a)),".rds"));if(file.exists(path))return(list(run=.trsc_retarget(readRDS(path),observed,protocol),hit=TRUE));p0<-protocol;p0$R<-0;base<-trsc_sim_post_feasible(observed,p0);trsc_sim_atomic_save(base,path);list(run=.trsc_retarget(base,observed,protocol),hit=FALSE)}
trsc_sim_run_frozen_attempt<-function(cell,repetition,frozen,output_dir="research/simulations/results",cache_dir=NULL){a<-trsc_sim_frozen_attempt(cell,repetition,frozen);path<-trsc_sim_result_path(output_dir,a);if(file.exists(path)){old<-readRDS(path);if(old$attempt$primary_key!=a$primary_key||old$attempt$registry_hash!=a$registry_hash)stop("Incompatible completed result.",call.=FALSE);return(old)};RNGkind("Mersenne-Twister","Inversion","Rejection");set.seed(a$seed);warns<-character();start<-proc.time()[[3]];value<-tryCatch(withCallingHandlers({lib<-trsc_sim_candidate_spec(cell$predictive_library,frozen);if(cell$layer=="pre_treatment_predictive"){obj<-trsc_sim_run_one(cell$scenario,a$seed,q=lib$q,kappa=lib$kappa,bandwidths=lib$bandwidths,T=as.integer(cell$T),J=as.integer(cell$J_requested),noise_sd=as.numeric(cell$sigma),reference_size=as.integer(cell$reference_size),raw_benchmark_kappa=as.numeric(cell$raw_benchmark_kappa),local_bandwidth=as.numeric(cell$local_bandwidth),tv_lambda=as.numeric(cell$tv_lambda));dims<-.trsc_verify_dimensions(cell,obj$scenario);list(kind="pre",selected=obj$selected,fit_metrics=obj$fit_metrics,benchmark_metrics=obj$benchmark_metrics,benchmark_cutoff=obj$benchmark_cutoff,selection_comparison=obj$selection_comparison,design_diagnostics=obj$design_diagnostics,solver_diagnostics=obj$solver_diagnostics,metadata=obj$metadata,effective_dimensions=dims)}else{d<-trsc_sim_post_scenario(cell$scenario,seed=a$seed,T=as.integer(cell$T),J=as.integer(cell$J_requested),H=as.integer(cell$H),rank=as.integer(cell$rank_requested),noise_sd=as.numeric(cell$sigma),gap=as.integer(cell$gap),velocity=as.numeric(cell$velocity),amplification=as.numeric(cell$amplification),near_distance=as.numeric(cell$near_distance),dependence=as.numeric(cell$dependence));dims<-.trsc_verify_dimensions(cell,d);rad<-trsc_sim_resolve_radius(cell,d$truth);p<-trsc_sim_post_protocol(as.integer(cell$structural_q),rad$R,predictive_q=lib$q,kappa=lib$kappa,bandwidths=lib$bandwidths,diameter_bound=as.numeric(cell$D));cached<-.trsc_cached_fit(d$observed,p,cell,a,cache_dir);met<-trsc_sim_post_frozen_metrics(cell,cached$run,d$truth,rad,frozen);list(kind="post",metrics=met,radius=rad,effective_dimensions=dims,fit_cache_hit=cached$hit)}},warning=function(w){warns<<-c(warns,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)e);a$runtime_seconds<-proc.time()[[3]]-start;a$warnings<-paste(warns,collapse=" | ");a$rng_kind<-paste(RNGkind(),collapse="/");if(inherits(value,"error")){a$status<-"error";a$error_class<-class(value)[1];a$message<-conditionMessage(value);value<-NULL}else{a$status<-"success";a$error_class<-NA_character_;a$message<-NA_character_};rec<-list(attempt=a,result=value);trsc_sim_atomic_save(rec,path);rec}
trsc_sim_combine_frozen<-function(output_dir="research/simulations/results",frozen=trsc_sim_validate_frozen_registries(),expected_attempts=trsc_sim_attempt_table(frozen)){files<-list.files(output_dir,"\\.rds$",recursive=TRUE,full.names=TRUE);files<-files[!grepl("/_fit_cache/",files)];if(!length(files))stop("No frozen-result shards found.",call.=FALSE);rec<-lapply(files,readRDS);atts<-lapply(rec,function(x)x$attempt);keys<-vapply(atts,function(x)x$primary_key,character(1));hs<-vapply(atts,function(x)x$registry_hash,character(1));if(any(hs!=frozen$registry_hash))stop("Incompatible registry hashes.",call.=FALSE);if(anyDuplicated(keys))stop("Duplicate primary keys.",call.=FALSE);if(any(!keys%in%expected_attempts$primary_key))stop("Attempt outside declared registry.",call.=FALSE);miss<-setdiff(expected_attempts$primary_key,keys);if(length(miss))stop("Missing ",length(miss)," declared attempts.",call.=FALSE);list(records=rec,attempts=do.call(rbind,lapply(atts,function(x)as.data.frame(x,stringsAsFactors=FALSE))),registry_hash=frozen$registry_hash)}

.trsc_mc_numeric_row<-function(values,cell_id,metric,n_attempted,n_failed){
 v<-as.numeric(values);v<-v[is.finite(v)];n<-length(v)
 s<-if(n>1)stats::sd(v)else NA_real_;mcse<-if(n>1)s/sqrt(n)else NA_real_
 q<-if(n)as.numeric(stats::quantile(v,c(.025,.975),names=FALSE,type=8))else c(NA_real_,NA_real_)
 data.frame(cell_id=cell_id,metric=metric,n_attempted=as.integer(n_attempted),
   n_failed=as.integer(n_failed),n=as.integer(n),mean=if(n)mean(v)else NA_real_,
   sd=s,mcse=mcse,empirical_q025=q[1],empirical_q975=q[2],stringsAsFactors=FALSE)
}
.trsc_mc_binomial_row<-function(values,cell_id,metric,n_attempted,n_failed,target){
 v<-values[!is.na(values)];n<-length(v);k<-sum(v)
 ci<-if(n)stats::binom.test(k,n)$conf.int else c(NA_real_,NA_real_)
 data.frame(cell_id=cell_id,metric=metric,n_attempted=as.integer(n_attempted),
   n_failed=as.integer(n_failed),n_evaluated=as.integer(n),successes=as.integer(k),
   frequency=if(n)k/n else NA_real_,mc_lower=ci[1],mc_upper=ci[2],
   coverage_target=target,stringsAsFactors=FALSE)
}
trsc_sim_frozen_report<-function(combined,frozen=trsc_sim_validate_frozen_registries()){
 if(!is.list(combined)||!all(c("records","attempts","registry_hash")%in%names(combined)))
   stop("combined must be a frozen combine result.",call.=FALSE)
 if(!identical(combined$registry_hash,frozen$registry_hash))
   stop("Report registry hash is incompatible with frozen registry.",call.=FALSE)
 a<-combined$attempts
 req<-c("cell_id","status")
 if(!is.data.frame(a)||!all(req%in%names(a)))stop("Combined attempts are malformed.",call.=FALSE)
 cells<-unique(as.character(a$cell_id))
 accounting<-do.call(rbind,lapply(cells,function(id){
   z<-a[a$cell_id==id,,drop=FALSE];att<-nrow(z);succ<-sum(z$status=="success");fail<-att-succ
   data.frame(cell_id=id,attempted=as.integer(att),successful=as.integer(succ),
     failed=as.integer(fail),failure_rate=if(att)fail/att else NA_real_,
     accounting_complete=(succ+fail)==att,stringsAsFactors=FALSE)
 }))
 rownames(accounting)<-NULL
 post_rows<-list();cover_rows<-list();pre_rows<-list();pi<-0L;ci<-0L;ri<-0L
 for(id in cells){
   acct<-accounting[accounting$cell_id==id,,drop=FALSE]
   recs<-combined$records[vapply(combined$records,function(x)identical(as.character(x$attempt$cell_id),id),logical(1))]
   good<-Filter(function(x)identical(x$attempt$status,"success")&&!is.null(x$result),recs)
   post<-Filter(function(x)identical(x$result$kind,"post"),good)
   if(length(post)){
     summaries<-lapply(post,function(x)x$result$metrics$summary)
     common<-Reduce(intersect,lapply(summaries,names))
     numeric_names<-common[vapply(common,function(nm)all(vapply(summaries,function(z)is.numeric(z[[nm]])&&length(z[[nm]])==1L,logical(1))),logical(1))]
     for(nm in numeric_names){pi<-pi+1L;post_rows[[pi]]<-.trsc_mc_numeric_row(
       vapply(summaries,function(z)as.numeric(z[[nm]]),numeric(1)),id,nm,acct$attempted,acct$failed)}
     targets<-c(
       true_path_in_coordinate_band="simultaneous coordinate-band coverage of the true untreated mean path",
       whole_set_sufficient_event="sufficient-event frequency; not exact whole-set coverage")
     for(nm in names(targets))if(nm%in%common&&all(vapply(summaries,function(z)is.logical(z[[nm]])&&length(z[[nm]])==1L,logical(1)))){
       ci<-ci+1L;cover_rows[[ci]]<-.trsc_mc_binomial_row(
         vapply(summaries,function(z)z[[nm]],logical(1)),id,nm,acct$attempted,acct$failed,targets[[nm]])}
   }
   pre<-Filter(function(x)identical(x$result$kind,"pre"),good)
   if(length(pre)){
     selected<-lapply(pre,function(x)x$result$selected)
     common<-Reduce(intersect,lapply(selected,names))
     numeric_names<-common[vapply(common,function(nm)all(vapply(selected,function(z)is.numeric(z[[nm]])&&length(z[[nm]])==1L,logical(1))),logical(1))]
     for(nm in numeric_names){ri<-ri+1L;pre_rows[[ri]]<-.trsc_mc_numeric_row(
       vapply(selected,function(z)as.numeric(z[[nm]]),numeric(1)),id,nm,acct$attempted,acct$failed)}
   }
 }
 bind<-function(x)if(length(x)){z<-do.call(rbind,x);rownames(z)<-NULL;z}else data.frame()
 list(attempt_accounting=accounting,pre_selected_numeric=bind(pre_rows),
      post_numeric=bind(post_rows),coverage=bind(cover_rows),
      registry_hash=frozen$registry_hash,
      interpretation=list(failure_denominator="all attempted repetitions",
        mcse="Monte Carlo standard error across finite successful numeric evaluations",
        empirical_quantiles="2.5% and 97.5% finite-replication quantiles",
        coverage_intervals="exact binomial Monte Carlo uncertainty, not causal confidence intervals"))
}

trsc_sim_select_cells<-function(frozen,cell=NULL,panel=NULL,shard_index=NULL,shard_count=NULL){x<-frozen$cells;if(!is.null(cell)){if(!all(cell%in%x$cell_id))stop("Undeclared cell.",call.=FALSE);x<-x[x$cell_id%in%cell,,drop=FALSE]};if(!is.null(panel)){if(!all(panel%in%frozen$cells$panel))stop("Undeclared panel.",call.=FALSE);x<-x[x$panel%in%panel,,drop=FALSE]};if(!is.null(shard_index)||!is.null(shard_count)){i<-as.integer(shard_index);n<-as.integer(shard_count);if(is.na(i)||is.na(n)||n<1||i<1||i>n)stop("Invalid shard.",call.=FALSE);x<-x[((x$cell_index-1L)%%n)+1L==i,,drop=FALSE]};x}
trsc_sim_git_state<-function(){paths<-tryCatch(system2("git",c("status","--porcelain"),stdout=TRUE),error=function(e)character());list(sha=tryCatch(system2("git",c("rev-parse","HEAD"),stdout=TRUE)[1],error=function(e)NA_character_),dirty=length(paths)>0,dirty_paths=paste(paths,collapse=" | "))}
trsc_sim_provenance_snapshot<-function(initial_sha=Sys.getenv("STAGE_A_INITIAL_SHA",unset=""),initial_dirty=Sys.getenv("STAGE_A_INITIAL_DIRTY",unset="")){post<-trsc_sim_git_state();sha<-if(is.character(initial_sha)&&length(initial_sha)==1&&!is.na(initial_sha)&&nzchar(initial_sha))initial_sha else post$sha;dirty<-if(is.logical(initial_dirty)&&length(initial_dirty)==1&&!is.na(initial_dirty))initial_dirty else if(is.character(initial_dirty)&&length(initial_dirty)==1&&!is.na(initial_dirty)&&tolower(initial_dirty)%in%c("true","false"))tolower(initial_dirty)=="true" else post$dirty;list(repository_sha=sha,dirty=dirty,post_check_dirty=post$dirty,post_check_dirty_paths=post$dirty_paths)}
trsc_sim_stage_a_preflight<-function(root="research/simulations",output_dir=file.path(root,"output","preflight"),ci_tests="not_recorded",ci_build="not_recorded",ci_check="not_recorded"){f<-trsc_sim_validate_frozen_registries(root);dir.create(output_dir,recursive=TRUE,showWarnings=FALSE);RNGkind("Mersenne-Twister","Inversion","Rejection");t<-proc.time()[[3]];pre<-trsc_sim_run_one("constant",11,q=1,kappa=.3,bandwidths=1,T=60,J=3,reference_size=200);pre_record<-list(kind="pre",selected=pre$selected,fit_metrics=pre$fit_metrics,benchmark_metrics=pre$benchmark_metrics,benchmark_cutoff=pre$benchmark_cutoff,selection_comparison=pre$selection_comparison,design_diagnostics=pre$design_diagnostics,solver_diagnostics=pre$solver_diagnostics,metadata=pre$metadata,effective_dimensions=list(J=pre$scenario$J,rank=NA_integer_));pre_s<-proc.time()[[3]]-t;t<-proc.time()[[3]];d<-trsc_sim_post_scenario("persistence",seed=12,T=60,J=3,H=5,rank=1);fixture_cell<-f$cells[f$cells$panel=="P0"&f$cells$scenario=="persistence"&f$cells$structural_q==1&f$cells$radius_rule=="rmin",][1,,drop=FALSE];fixture_cell$T<-60;fixture_cell$J_requested<-3;fixture_cell$J_effective<-3;fixture_cell$rank_requested<-1;fixture_cell$rank_effective<-1;fixture_cell$H<-5;fixture_cell$gap<-10;fixture_cell$velocity_rule<-"0.05/T";fixture_cell$velocity<-.05/60;fixture_cell$predictive_library<-"L12";rad<-trsc_sim_resolve_radius(fixture_cell,d$truth);lib<-trsc_sim_candidate_spec("L12",f);pr<-trsc_sim_post_feasible(d$observed,trsc_sim_post_protocol(1,rad$R,predictive_q=lib$q,kappa=lib$kappa,bandwidths=lib$bandwidths,diameter_bound=fixture_cell$D));pm<-trsc_sim_post_frozen_metrics(fixture_cell,pr,d$truth,rad,f);post_record<-list(kind="post",metrics=pm,radius=rad,effective_dimensions=list(J=3L,rank=1L),fit_cache_hit=FALSE);post_s<-proc.time()[[3]]-t;pc<-aggregate(repetitions~panel,f$cells,sum);pc$fixture_seconds<-ifelse(grepl("^E",pc$panel),pre_s,post_s);pc$fixture_serialized_bytes<-ifelse(grepl("^E",pc$panel),length(serialize(pre_record,NULL)),length(serialize(post_record,NULL)));pc$estimated_seconds<-pc$repetitions*pc$fixture_seconds;pc$estimated_storage_bytes<-pc$repetitions*pc$fixture_serialized_bytes;pc$estimate_note<-"linear extrapolation from reserved-seed smoke fixture; not a scientific result";write.csv(pc,file.path(output_dir,"runtime_estimates.csv"),row.names=FALSE);v<-vapply(c("osqp","ECOSolveR","gmp"),function(p)as.character(packageVersion(p)),character(1));g<-trsc_sim_provenance_snapshot();m<-data.frame(schema_version=1,repository_sha=g$repository_sha,dirty=g$dirty,post_check_dirty=g$post_check_dirty,post_check_dirty_paths=g$post_check_dirty_paths,design_sha256=f$hashes[["design"]],historical_design_sha256=.trsc_stage_a$historical_design_sha256,cell_registry_sha256=f$hashes[["cells"]],candidate_library_sha256=f$hashes[["candidates"]],deployment_epsilon_sha256=f$hashes[["epsilon"]],cell_count=f$cell_count,attempted_repetitions=f$attempted_repetitions,R_version=R.version.string,TRSC_version=as.character(packageVersion("TRSC")),osqp_version=v[["osqp"]],ECOSolveR_version=v[["ECOSolveR"]],gmp_version=v[["gmp"]],RNGkind=paste(RNGkind(),collapse="/"),tests=ci_tests,build=ci_build,check=ci_check,execution_contract=trsc_sim_execution_gate(f)$status,nominal_inference_protocol=trsc_sim_nominal_inference_gate()$status,scientific_repetitions_executed=0,stringsAsFactors=FALSE);write.csv(m,file.path(output_dir,"preflight_manifest.csv"),row.names=FALSE);writeLines(capture.output(sessionInfo()),file.path(output_dir,"sessionInfo.txt"));saveRDS(list(pre=pre_record,post=post_record),file.path(output_dir,"non_scientific_fixture.rds"));invisible(list(manifest=m,runtime_estimates=pc))}
